const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const AWS = require('aws-sdk');
const _ = require('lodash');

// In-memory settings store
let serverSettings = {
  cache: { ttl: 300, maxSize: 1000 },
  features: { darkMode: false, betaAccess: false },
  rateLimit: { windowMs: 60000, max: 100 }
};

const typeDefs = gql`
  scalar JSON

  type Query {
    getSettings(path: String): JSON
    getFeatureFlags: JSON
  }

  type Mutation {
    updateSettings(path: String!, value: JSON!): JSON
    mergeConfig(config: JSON!): JSON
    resetSettings: JSON
  }
`;

const resolvers = {
  Query: {
    getSettings: (_, { path }) => {
      if (!path) return serverSettings;
      return _.get(serverSettings, path);
    },
    getFeatureFlags: () => serverSettings.features
  },
  Mutation: {
    updateSettings: (_, { path, value }) => {
      // Deep set allows arbitrary path traversal
      _.set(serverSettings, path, value);
      return serverSettings;
    },
    mergeConfig: (_, { config }) => {
      // Vulnerable: recursive merge without prototype pollution guard
      // lodash < 4.17.12 is vulnerable, but even in newer versions
      // the path-based set above allows __proto__ pollution
      const merged = _.merge({}, serverSettings, config);
      serverSettings = merged;
      return serverSettings;
    },
    resetSettings: () => {
      serverSettings = {
        cache: { ttl: 300, maxSize: 1000 },
        features: { darkMode: false, betaAccess: false },
        rateLimit: { windowMs: 60000, max: 100 }
      };
      return serverSettings;
    }
  }
};

// Post-processing middleware that uses polluted prototype
const executeAction = async (actionType) => {
  const s3 = new AWS.S3();
  const lambda = new AWS.Lambda();

  const opts = {};

  // If prototype is polluted, opts.admin will be true
  if (opts.admin) {
    // Dangerous: allows arbitrary Lambda invocation
    const params = {
      FunctionName: opts.functionName || 'admin-data-export',
      InvocationType: 'RequestResponse',
      Payload: JSON.stringify({ action: actionType })
    };
    return lambda.invoke(params).promise();
  }

  if (opts.s3Export) {
    // Dangerous: allows writing to arbitrary S3 bucket
    const params = {
      Bucket: opts.bucket || 'internal-exports',
      Key: `export-${Date.now()}.json`,
      Body: JSON.stringify(serverSettings)
    };
    return s3.putObject(params).promise();
  }

  return { status: 'no-op' };
};

const app = express();

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: true,
  playground: true
});

server.applyMiddleware({ app });

// Health check that triggers action processing
app.get('/process/:action', async (req, res) => {
  try {
    const result = await executeAction(req.params.action);
    res.json(result);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(4000, () => {
  console.log('GraphQL server running on port 4000');
});

module.exports = { app, serverSettings };
